type PPP_PCB struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	PID          *PID                  `hl7:"PID,required"`
	PATIENTVISIT *PPP_PCB_PATIENTVISIT `hl7:"PATIENT VISIT"`
	PATHWAY      []PPP_PCB_PATHWAY     `hl7:"PATHWAY,required"`
}

