// REF_I14 - Cancel patient referral
// This event triggers a message to be sent from one healthcare provider to another canceling a referral.  A previous referral may have been made in error, or perhaps the cancellation has come from the patient
type REF_I14 struct {
	MSH                  *MSH                          `hl7:"MSH,required"`
	RF1                  *RF1                          `hl7:"RF1"`
	AUTHORIZATIONCONTACT *REF_I14_AUTHORIZATIONCONTACT `hl7:"AUTHORIZATION CONTACT"`
	PROVIDER             []REF_I14_PROVIDER            `hl7:"PROVIDER,required"`
	PID                  *PID                          `hl7:"PID,required"`
	NK1                  []NK1                         `hl7:"NK1"`
	GT1                  []GT1                         `hl7:"GT1"`
	INSURANCE            []REF_I14_INSURANCE           `hl7:"INSURANCE"`
	ACC                  *ACC                          `hl7:"ACC"`
	DG1                  []DG1                         `hl7:"DG1"`
	DRG                  []DRG                         `hl7:"DRG"`
	AL1                  []AL1                         `hl7:"AL1"`
	PROCEDURE            []REF_I14_PROCEDURE           `hl7:"PROCEDURE"`
	OBSERVATION          []REF_I14_OBSERVATION         `hl7:"OBSERVATION"`
	PATIENTVISIT         *REF_I14_PATIENTVISIT         `hl7:"PATIENT VISIT"`
	NTE                  []NTE                         `hl7:"NTE"`
}

