// SRM_S01 - Request new appointment booking
// A placer application sends a transaction with this trigger event to a filler application to request that a new appointment be booked.  If it is successful, the filler application returns an application acknowledgment (if requested under the enhanced acknowledgment mode, or if the original acknowledgment mode is in use).  The acknowledgment may optionally contain an SCH segment and related detail segments describing the actual appointment that was booked.
type SRM_S01 struct {
	MSH       *MSH                `hl7:"MSH,required"`
	ARQ       *ARQ                `hl7:"ARQ,required"`
	APR       *APR                `hl7:"APR"`
	NTE       []NTE               `hl7:"NTE"`
	PATIENT   []SRM_S01_PATIENT   `hl7:"PATIENT"`
	RESOURCES []SRM_S01_RESOURCES `hl7:"RESOURCES,required"`
}

func NewSRM_S01() *SRM_S01 {
	return &SRM_S01{
		MSH: NewMSH(NewCM_MSG().SetMessageType("SRM").SetTriggerEvent("S01")),
	}
}

func (m *SRM_S01) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("SRM_S01.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("SRM_S01.MSH: %w", err)
		}
	}

	if m.ARQ == nil {
		return fmt.Errorf("SRM_S01.ARQ is required")
	}
	if m.ARQ != nil {
		if err := m.ARQ.Validate(); err != nil {
			return fmt.Errorf("SRM_S01.ARQ: %w", err)
		}
	}

	if m.APR != nil {
		if err := m.APR.Validate(); err != nil {
			return fmt.Errorf("SRM_S01.APR: %w", err)
		}
	}

	for _, item := range m.NTE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S01.NTE: %w", err)
		}
	}

	for _, item := range m.PATIENT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S01.PATIENT: %w", err)
		}
	}

	if len(m.RESOURCES) == 0 {
		return fmt.Errorf("SRM_S01.RESOURCES is required")
	}
	for _, item := range m.RESOURCES {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S01.RESOURCES: %w", err)
		}
	}
	return nil
}

