// SRM_S03 - Request appointment modification
// This message transmits a request for modification of an existing appointment to a filler application.  This trigger event is used to request the modification of information on an existing appointment, outside of the need to reschedule, cancel, discontinue or delete the appointment, or to add, modify, cancel, discontinue, or delete services and/or resources on the appointment.  This trigger event should only be used for appointments that have not been completed, or for parent appointments whose children have not been completed.  If it is successful, an application acknowledgment is returned, optionally containing an SCH segment and related detail segments describing the new information for the modified appointment
type SRM_S03 struct {
	MSH       *MSH                `hl7:"MSH,required"`
	ARQ       *ARQ                `hl7:"ARQ,required"`
	APR       *APR                `hl7:"APR"`
	NTE       []NTE               `hl7:"NTE"`
	PATIENT   []SRM_S03_PATIENT   `hl7:"PATIENT"`
	RESOURCES []SRM_S03_RESOURCES `hl7:"RESOURCES,required"`
}

func NewSRM_S03() *SRM_S03 {
	return &SRM_S03{
		MSH: NewMSH(NewCM_MSG().SetMessageType("SRM").SetTriggerEvent("S03")),
	}
}

func (m *SRM_S03) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("SRM_S03.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("SRM_S03.MSH: %w", err)
		}
	}

	if m.ARQ == nil {
		return fmt.Errorf("SRM_S03.ARQ is required")
	}
	if m.ARQ != nil {
		if err := m.ARQ.Validate(); err != nil {
			return fmt.Errorf("SRM_S03.ARQ: %w", err)
		}
	}

	if m.APR != nil {
		if err := m.APR.Validate(); err != nil {
			return fmt.Errorf("SRM_S03.APR: %w", err)
		}
	}

	for _, item := range m.NTE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S03.NTE: %w", err)
		}
	}

	for _, item := range m.PATIENT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S03.PATIENT: %w", err)
		}
	}

	if len(m.RESOURCES) == 0 {
		return fmt.Errorf("SRM_S03.RESOURCES is required")
	}
	for _, item := range m.RESOURCES {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S03.RESOURCES: %w", err)
		}
	}
	return nil
}

