// SRM_S06 - Request appointment deletion
// A request appointment deletion is sent by the placer application to the filler application to request that an appointment that had been entered in error be removed from the system.  A delete trigger event should only be used when an appointment has been erroneously requested, and must be removed from the schedule so that it does not affect any statistical processing.  A delete trigger event differs from a cancel trigger event in that a delete acts to remove an error, whereas a cancel acts to prevent a valid request from occurring.This trigger event should not be used for any appointment that has already begun, or has already been completed.  Likewise, it should not be used on any parent appointment if any child appointments have either begun or been completed.  If it is successful, an application acknowledgment is returned, optionally containing an SCH segment and related detail segments describing the deleted appointment.
type SRM_S06 struct {
	MSH       *MSH                `hl7:"MSH,required"`
	ARQ       *ARQ                `hl7:"ARQ,required"`
	APR       *APR                `hl7:"APR"`
	NTE       []NTE               `hl7:"NTE"`
	PATIENT   []SRM_S06_PATIENT   `hl7:"PATIENT"`
	RESOURCES []SRM_S06_RESOURCES `hl7:"RESOURCES,required"`
}

func NewSRM_S06() *SRM_S06 {
	return &SRM_S06{
		MSH: NewMSH(NewCM_MSG().SetMessageType("SRM").SetTriggerEvent("S06")),
	}
}

func (m *SRM_S06) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("SRM_S06.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("SRM_S06.MSH: %w", err)
		}
	}

	if m.ARQ == nil {
		return fmt.Errorf("SRM_S06.ARQ is required")
	}
	if m.ARQ != nil {
		if err := m.ARQ.Validate(); err != nil {
			return fmt.Errorf("SRM_S06.ARQ: %w", err)
		}
	}

	if m.APR != nil {
		if err := m.APR.Validate(); err != nil {
			return fmt.Errorf("SRM_S06.APR: %w", err)
		}
	}

	for _, item := range m.NTE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S06.NTE: %w", err)
		}
	}

	for _, item := range m.PATIENT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S06.PATIENT: %w", err)
		}
	}

	if len(m.RESOURCES) == 0 {
		return fmt.Errorf("SRM_S06.RESOURCES is required")
	}
	for _, item := range m.RESOURCES {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S06.RESOURCES: %w", err)
		}
	}
	return nil
}

