// SRR_S08 - Response modification of service/resource on appointment
// The request modification of service/resource is triggered on the placer application to request that information pertaining to an existing service or resource be changed for an existing appointment.  Services and resources are represented by the AIS, AIG, AIL, and AIP segments on an HL7 scheduling interface transaction.  This trigger event should only be used for appointments that have not been completed, or for parent appointments whose children have not been completed.  If it is successful, an application acknowledgment is returned, optionally containing an SCH segment and related detail segments describing the modified appointment
type SRR_S08 struct {
	MSH      *MSH              `hl7:"MSH,required"`
	MSA      *MSA              `hl7:"MSA,required"`
	ERR      *ERR              `hl7:"ERR"`
	SCHEDULE *SRR_S08_SCHEDULE `hl7:"SCHEDULE"`
}

func NewSRR_S08() *SRR_S08 {
	return &SRR_S08{
		MSH: NewMSH(NewCM_MSG().SetMessageType("SRR").SetTriggerEvent("S08")),
	}
}

func (m *SRR_S08) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("SRR_S08.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("SRR_S08.MSH: %w", err)
		}
	}

	if m.MSA == nil {
		return fmt.Errorf("SRR_S08.MSA is required")
	}
	if m.MSA != nil {
		if err := m.MSA.Validate(); err != nil {
			return fmt.Errorf("SRR_S08.MSA: %w", err)
		}
	}

	if m.ERR != nil {
		if err := m.ERR.Validate(); err != nil {
			return fmt.Errorf("SRR_S08.ERR: %w", err)
		}
	}

	if m.SCHEDULE != nil {
		if err := m.SCHEDULE.Validate(); err != nil {
			return fmt.Errorf("SRR_S08.SCHEDULE: %w", err)
		}
	}
	return nil
}

