// VXX_V02 - Response to vaccination query
// In response to a query for the definitive patient vaccination record, the system holding the record will return it to the system originating the query
type VXX_V02 struct {
	MSH     *MSH              `hl7:"MSH,required"`
	MSA     *MSA              `hl7:"MSA,required"`
	QRD     *QRD              `hl7:"QRD,required"`
	QRF     *QRF              `hl7:"QRF"`
	PATIENT []VXX_V02_PATIENT `hl7:"PATIENT,required"`
}

func NewVXX_V02() *VXX_V02 {
	return &VXX_V02{
		MSH: NewMSH(NewCM_MSG().SetMessageType("VXX").SetTriggerEvent("V02")),
	}
}

func (m *VXX_V02) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("VXX_V02.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("VXX_V02.MSH: %w", err)
		}
	}

	if m.MSA == nil {
		return fmt.Errorf("VXX_V02.MSA is required")
	}
	if m.MSA != nil {
		if err := m.MSA.Validate(); err != nil {
			return fmt.Errorf("VXX_V02.MSA: %w", err)
		}
	}

	if m.QRD == nil {
		return fmt.Errorf("VXX_V02.QRD is required")
	}
	if m.QRD != nil {
		if err := m.QRD.Validate(); err != nil {
			return fmt.Errorf("VXX_V02.QRD: %w", err)
		}
	}

	if m.QRF != nil {
		if err := m.QRF.Validate(); err != nil {
			return fmt.Errorf("VXX_V02.QRF: %w", err)
		}
	}

	if len(m.PATIENT) == 0 {
		return fmt.Errorf("VXX_V02.PATIENT is required")
	}
	for _, item := range m.PATIENT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("VXX_V02.PATIENT: %w", err)
		}
	}
	return nil
}

